export interface ZtIconProps {
  /** 内置图标名称。默认插槽和 component 的优先级更高。 */
  name?: ZtIconName
  /** 自定义 Vue 图标组件。 */
  component?: Component
  /** 图标 CSS 尺寸；正数按像素处理，默认 1em。 */
  size?: number | string
  /** 自定义图标颜色，覆盖 status。 */
  color?: string
  /** 图标主题颜色。 */
  status?: ZtIconStatus
  /** 顺时针旋转角度。 */
  rotate?: number
  /** 是否持续旋转；系统减少动画时停止。 */
  spin?: boolean
  /** 内置线性图标的描边宽度。 */
  strokeWidth?: number
  /** 图标的无障碍名称；未设置时视为装饰内容。 */
  label?: string
}

export interface ZtLinkProps{
 /** 原生链接地址。 */
 href?:string
 /** Vue Router 路由目标；没有 Router 时字符串目标回退为 href。 */
 to?:ZtLinkRoute
 /** 路由导航时使用 replace。 */
 replace?:boolean
 /** 原生链接打开目标。 */
 target?:string
 /** 原生链接关系；target=_blank 时默认补充安全值。 */
 rel?:string
 /** 原生下载属性。 */
 download?:string|boolean
 /** 链接主题颜色。 */
 status?:ZtLinkStatus
 /** 链接尺寸，默认继承 ConfigProvider。 */
 size?:ZtComponentSize
 /** 禁用导航、点击事件和键盘聚焦。 */
 disabled?:boolean
 /** 下划线显示策略。 */
 underline?:ZtLinkUnderline
 /** 左侧内置图标名或 Vue 图标组件。 */
 icon?:ZtIconName|Component
 /** 右侧内置图标名或 Vue 图标组件。 */
 suffixIcon?:ZtIconName|Component
}

export interface ZtTextProps{
 /** 安全的 HTML 语义标签。 */
 tag?:ZtTextTag
 /** 文本主题颜色。 */
 status?:ZtTextStatus
 /** 文本尺寸，默认继承 ConfigProvider。 */
 size?:ZtComponentSize
 /** 预设或数值字重。 */
 weight?:ZtTextWeight
 /** 单行溢出时显示省略号。 */
 truncated?:boolean
 /** 多行省略的最大行数，优先于 truncated。 */
 lineClamp?:number
 /** 原生 title；截断纯文本未设置时自动生成。 */
 title?:string
}

export interface ZtScrollbarProps{
 /** 滚动区域高度，数值按像素处理。 */
 height?:number|string
 /** 滚动区域最大高度，数值按像素处理。 */
 maxHeight?:number|string
 /** 使用系统原生滚动条。 */
 native?:boolean
 /** 内容溢出时始终显示自定义轨道。 */
 always?:boolean
 /** 自定义滑块最小长度，单位像素。 */
 minSize?:number
 /** 关闭 ResizeObserver 自动尺寸更新。 */
 noresize?:boolean
 /** 滚动容器的附加类。 */
 wrapClass?:string|string[]|Record<string,boolean>
 /** 滚动容器的附加样式。 */
 wrapStyle?:CSSProperties|string
 /** 内容视图的附加类。 */
 viewClass?:string|string[]|Record<string,boolean>
 /** 内容视图的附加样式。 */
 viewStyle?:CSSProperties|string
 /** 内容视图使用的 HTML 标签。 */
 tag?:string
 /** 轨道密度尺寸，默认继承 ConfigProvider。 */
 size?:ZtComponentSize
}

export interface ZtPopoverProps {
  /** 浮层是否显示，支持 v-model:visible。 */ visible?: boolean;
  /** 触发方式。 */ trigger?: ZtPopoverTrigger;
  /** 首选出现方位，空间不足时自动翻转。 */ placement?: ZtPopoverPlacement;
  /** 浮层宽度，数值按像素处理。 */ width?: number | string;
  /** 浮层与触发器的间距。 */ offset?: number;
  /** 禁用全部打开交互。 */ disabled?: boolean;
  /** 是否显示指向触发器的箭头。 */ showArrow?: boolean;
  /** 是否 Teleport 到 body。 */ teleported?: boolean;
  /** 打开延迟毫秒数。 */ openDelay?: number;
  /** 关闭延迟毫秒数。 */ closeDelay?: number;
  /** 浮层层级。 */ zIndex?: number;
  /** 关闭时将焦点返回触发器；输入建议类浮层可关闭以保留正常 Tab 顺序。 */ restoreFocus?: boolean;
  /** 关闭后保留浮层 DOM。 */ persistent?: boolean;
}

export interface ZtPopoverInstance {
  show: () => void;
  hide: () => void;
  toggle: () => void;
  updatePosition: () => void;
}

export interface ZtPopconfirmProps{
 /** 是否显示，支持 v-model:visible。 */ visible?:boolean
 /** 确认标题。 */ title:string
 /** 补充说明。 */ description?:string
 /** 语义主题颜色。 */ status?:ZtPopconfirmStatus
 /** 内置图标名或 Vue 图标组件。 */ icon?:ZtIconName|Component
 /** 隐藏状态图标。 */ hideIcon?:boolean
 /** 确认按钮文字。 */ confirmText?:string
 /** 取消按钮文字。 */ cancelText?:string
 /** 按钮尺寸。 */ buttonSize?:ZtComponentSize
 /** 外部确认加载状态。 */ confirmLoading?:boolean
 /** 禁用确认按钮。 */ confirmDisabled?:boolean
 /** 禁用取消按钮。 */ cancelDisabled?:boolean
 /** 成功确认后关闭。 */ hideAfterConfirm?:boolean
 /** 确认前钩子；返回 false 或拒绝时保持打开。 */ beforeConfirm?:()=>boolean|void|Promise<boolean|void>
 /** 浮层方位。 */ placement?:ZtPopoverPlacement
 /** 整体禁用。 */ disabled?:boolean
}

export interface ZtTabsProps{
 /** 当前标签名称，支持 v-model。 */ modelValue?:ZtTabName
 /** 标签外观。 */ type?:ZtTabsType
 /** 标签导航位置。 */ position?:ZtTabsPosition
 /** 全部标签允许关闭。 */ closable?:boolean
 /** 显示新增按钮。 */ addable?:boolean
 /** 同时启用新增和关闭。 */ editable?:boolean
 /** 标签平均铺满可用空间。 */ stretch?:boolean
 /** 切换前守卫，返回 false 或拒绝时保留当前项。 */ beforeLeave?:(next:ZtTabName,previous:ZtTabName)=>boolean|void|Promise<boolean|void>
 /** 选中主题颜色。 */ status?:ZtTabsStatus
 /** 尺寸，默认继承 ConfigProvider。 */ size?:ZtComponentSize
}

export interface ZtTabPaneProps{
 /** 标签唯一名称。 */ name:ZtTabName
 /** 标签文字。 */ label?:string
 /** 禁用选择。 */ disabled?:boolean
 /** 当前标签允许关闭。 */ closable?:boolean
 /** 首次激活时才渲染内容。 */ lazy?:boolean
}

export interface ZtBreadcrumbProps {
  /** 分隔符文字。 */ separator?: string
  /** 尺寸，默认继承 ConfigProvider。 */ size?: ZtComponentSize
  /** 导航的无障碍名称。 */ ariaLabel?: string
}

export interface ZtBreadcrumbItemProps {
  /** 原生链接地址。 */ href?: string
  /** Vue Router 路由目标。 */ to?: string | Record<string, unknown>
  /** 禁用导航。 */ disabled?: boolean
  /** 链接打开位置。 */ target?: string
}

export interface ZtSegmentedProps {
  /** 当前值，支持 v-model。 */ modelValue?: ZtSegmentedValue
  /** 字符串、数字、布尔值或完整选项。 */ options: Array<ZtSegmentedValue | ZtSegmentedOption>
  /** 整体禁用。 */ disabled?: boolean
  /** 平均铺满容器。 */ block?: boolean
  /** 选中主题颜色。 */ status?: ZtSegmentedStatus
  /** 尺寸，默认继承 ConfigProvider。 */ size?: ZtComponentSize
  /** 无障碍名称。 */ ariaLabel?: string
}

export interface ZtDescriptionsProps {
  /** 标题。 */ title?: string
  /** 桌面端列数。 */ column?: number
  /** 是否显示边框。 */ border?: boolean
  /** 标签宽度。 */ labelWidth?: string | number
  /** 标签位置。 */ direction?: 'horizontal' | 'vertical'
  /** 尺寸，默认继承 ConfigProvider。 */ size?: ZtComponentSize
}

export interface ZtDescriptionsItemProps {
  /** 标签文字。 */ label?: string
  /** 占据列数。 */ span?: number
  /** 自定义标签宽度。 */ labelWidth?: string | number
  /** 自定义内容类名。 */ className?: string
}

export interface ZtCollapseProps {
 /** 展开的面板名称，支持 v-model。 */ modelValue?:ZtCollapseName|ZtCollapseName[]
 /** 手风琴模式。 */ accordion?:boolean
 /** 尺寸，默认继承 ConfigProvider。 */ size?:ZtComponentSize
}

export interface ZtCollapseItemProps {
 /** 面板唯一名称。 */ name:ZtCollapseName
 /** 标题。 */ title?:string
 /** 禁用面板。 */ disabled?:boolean
 /** 首次展开时才渲染内容。 */ lazy?:boolean
}

export interface ZtResultProps{
 /** 结果状态或 HTTP 状态。 */status?:ZtResultStatus
 /** 主标题。 */title?:string
 /** 补充说明。 */subTitle?:string
 /** 自定义图标名。 */icon?:ZtIconName
}

export interface ZtImageProps{
 /** 图片地址。 */src:string
 /** 替代文字。 */alt?:string
 /** object-fit 模式。 */fit?:ZtImageFit
 /** object-position。 */position?:string
 /** 启用原生懒加载。 */lazy?:boolean
 /** 预览图片地址列表。 */previewSrcList?:string[]
 /** 预览初始索引。 */initialIndex?:number
 /** 是否循环预览。 */infinite?:boolean
 /** 点击遮罩关闭预览。 */hideOnClickModal?:boolean
 /** Escape 关闭预览。 */closeOnPressEscape?:boolean
 /** 预览层级。 */zIndex?:number
}

export interface ZtImageViewerProps{
 /** 图片地址列表。 */urls:string[]
 /** 初始索引。 */initialIndex?:number
 /** 是否循环。 */infinite?:boolean
 /** 缩放倍率。 */zoomRate?:number
 /** 最小缩放。 */minScale?:number
 /** 最大缩放。 */maxScale?:number
 /** 点击遮罩关闭。 */hideOnClickModal?:boolean
 /** Escape 关闭。 */closeOnPressEscape?:boolean
 /** 层级。 */zIndex?:number
}

export interface ZtAvatarProps{
 /** 图片地址。 */src?:string
 /** 响应式图片集合。 */srcSet?:string
 /** 图片替代文字及文字后备。 */alt?:string
 /** 头像尺寸。 */size?:ZtAvatarSize
 /** 形状。 */shape?:ZtAvatarShape
 /** 图片适应方式。 */fit?:'fill'|'contain'|'cover'|'none'|'scale-down'
 /** 状态主题。 */status?:ZtAvatarStatus
 /** 后备图标名。 */icon?:ZtIconName|Component
}

export interface ZtUploadProps {
 /** 文件列表，支持 v-model:file-list。回显项需有唯一 uid、name 和 status。 */
 fileList?: ZtUploadFile[]
 /** 上传地址。默认请求使用 multipart/form-data；未配置地址或自定义请求时仅选择文件。 */
 action?: string
 /** 请求方法。 */
 method?: string
 /** multipart 文件字段名。 */
 name?: string
 /** 附加请求头。 */
 headers?: Record<string,string>
 /** 附加表单字段。 */
 data?: Record<string,string | number | boolean | Blob>
 /** 跨域请求是否携带 Cookie 等凭据。 */
 withCredentials?: boolean
 /** 请求超时毫秒数，0 表示不限。 */
 timeout?: number
 /** 接受的扩展名或 MIME，逗号分隔；选择和拖拽都会校验。 */
 accept?: string
 /** 允许一次选择多个文件；false 时批量拖入只取第一个文件。 */
 multiple?: boolean
 /** 列表最多容纳文件数，0 不限制。批量选择超限时整批拒绝并触发 exceed。 */
 limit?: number
 /** 单个文件上限，单位 MB，0 不限制。 */
 maxSize?: number
 /** 选择完成后自动上传；false 时通过 submit() 上传。 */
 autoUpload?: boolean
 /** 开启拖拽区域。 */
 drag?: boolean
 disabled?: boolean
 size?: ZtComponentSize
 status?: ZtUploadStatus
 /** 列表样式：普通文件、图片缩略图列表或照片墙。照片墙达到 limit 时隐藏添加入口。 */
 listType?: 'text' | 'picture' | 'picture-card'
 /** 是否展示文件列表。 */
 showFileList?: boolean
 /** 文件加入列表前的异步校验，可返回 false 拒绝或返回 File / Blob 替换上传内容。 */
 beforeUpload?: (file: File) => boolean | void | File | Blob | Promise<boolean | void | File | Blob>
 /** 移除前校验，返回 false 或 Promise 拒绝时保留文件。 */
 beforeRemove?: (file: ZtUploadFile, files: ZtUploadFile[]) => boolean | void | Promise<boolean | void>
 /** 已封装的业务接口方法。组件传入 FormData 和请求上下文，可直接复用 Axios 实例及其拦截器。 */
 request?: ZtUploadSubmitRequest
 /** 自定义上传：返回 Promise 或调用回调；通过 signal 或返回 abort() 支持取消。 */
 httpRequest?: ZtUploadRequest
}

export interface ZtInputOtpProps {
  /** 输入值。使用字符串以保留开头的 0。 */
  modelValue?: string | null
  /** 验证码位数，1–32，默认 6。 */
  length?: number
  /** 仅接受数字；关闭后允许非空白字符。全角数字会转换为半角。 */
  integerOnly?: boolean
  /** 遮蔽已输入字符，不影响绑定值。 */
  mask?: boolean
  /** 默认继承 Form / ConfigProvider 的尺寸。 */
  size?: ZtComponentSize
  /** 主题或校验状态，error 为 danger 的别名。 */
  status?: ZtInputOtpStatus
  /** 禁用输入，可继承 Form。 */
  disabled?: boolean
  /** 只读。 */
  readonly?: boolean
  /** 两组字符之间的分隔文本，例如 "-"。 */
  separator?: string
  /** 在第几格后显示分隔符，默认位数的一半（向下取整）。 */
  separatorAfter?: number
  /** 浏览器自动填充提示，默认 one-time-code。 */
  autocomplete?: string
  /** 挂载时自动聚焦，默认关闭。 */
  autofocus?: boolean
}

export interface ZtMenuItem {
  /** 唯一标识，包含分组和子菜单在内均不可重复。 */
  key: string
  /** 显示文本。 */
  label: string
  /** 分组标题，不参与选择；children 为组内菜单。 */
  type?: 'group'
  /** 子菜单或分组内容。 */
  children?: ZtMenuItem[]
  /** 禁用当前项及其后代。 */
  disabled?: boolean
  /** 辅助说明，显示在菜单右侧。 */
  description?: string
  /** Vue 图标组件。 */
  icon?: Component
  /** 叶子菜单链接。不依赖 Vue Router，可在 select 事件中阻止默认导航。 */
  href?: string
  /** router 模式的目标路由；未设置时以 key 作为路径。支持命名路由、params、query 和 hash。href 显式设置时仍按普通链接处理。 */
  route?: ZtMenuRoute
}

export interface ZtMenuProps {
  /** 当前选中叶子项的 key，支持 v-model。 */
  modelValue?: string
  /** 菜单配置，支持分组和多级子菜单。 */
  items?: ZtMenuItem[]
  /** 纵向/双栏树中展开的子菜单 key；支持 v-model:expanded-keys。 */
  expandedKeys?: string[]
  /** 非受控模式的初始展开项。 */
  defaultExpandedKeys?: string[]
  /** 同一父级下只展开一个子菜单。 */
  accordion?: boolean
  /** 禁用全部交互。 */
  disabled?: boolean
  /** 尺寸，默认继承 ConfigProvider。 */
  size?: ZtComponentSize
  /** 选中项的主题颜色。 */
  status?: ZtMenuStatus
  /** 布局：纵向树形、模块与内容双栏、横向导航。横向模式不使用折叠和宽度拖动。 */
  mode?: 'vertical' | 'double' | 'horizontal'
  /** 启用应用已安装的 Vue Router，点击叶子项跳转并跟随当前路由选中。 */
  router?: boolean
  /** 横向子菜单触发方式；键盘和触屏始终支持点击。 */
  menuTrigger?: 'hover' | 'click'
  /** 整栏折叠，支持 v-model:collapsed；折叠时点击父菜单弹出子菜单，选择叶子项后自动收起浮层。 */
  collapsed?: boolean
  /** 显示底部折叠按钮。 */
  collapsible?: boolean
  /** default 尺寸下的展开基准宽度；其他 size 加上对应偏移（mini -60、small -32、medium +28、large +56px）。支持数字、CSS 长度及 v-model:width；拖动回传基准值。 */
  width?: number | string
  /** default 尺寸下的折叠基准宽度，单位 px；其他 size 偏移为 -8/-4/+4/+8px；双栏折叠时最小 60px，保留四字标签空间。 */
  collapsedWidth?: number
  /** default 尺寸下的双栏主栏基准宽度，单位 px；其他 size 偏移为 -4/0/+4/+8px；不低于对应尺寸的默认主栏宽度。 */
  railWidth?: number
  /** 允许拖动右边缘调整展开宽度。 */
  resizable?: boolean
  /** 拖动宽度的最小值。 */
  minWidth?: number
  /** 拖动宽度的最大值。 */
  maxWidth?: number
  /** 双栏模式当前业务模块 key，支持 v-model:active-key。 */
  activeKey?: string
  /** 菜单的无障碍名称。 */
  ariaLabel?: string
}

export interface ZtSliderProps {
  /** 当前数值；range 时使用 [起点, 终点]。 */
  modelValue?: ZtSliderValue
  /** 最小值。 */
  min?: number
  /** 最大值，必须大于 min；否则禁用交互。 */
  max?: number
  /** 步长，以 min 为起点；无效值按 1 处理。 */
  step?: number
  /** 双滑块范围选择，不允许交叉。 */
  range?: boolean
  /** 禁用交互。 */
  disabled?: boolean
  /** 尺寸，默认继承 Form 或 ConfigProvider。 */
  size?: ZtComponentSize
  /** 主题颜色。 */
  status?: ZtSliderStatus
  /** 悬停、拖动或键盘聚焦时显示数值。 */
  showTooltip?: boolean
  /** 格式化数值提示和辅助技术读数。 */
  formatTooltip?: (value: number) => string
  /** 控件的无障碍名称，范围模式会附加起点或终点。 */
  ariaLabel?: string
}

export interface ZtProgressProps {
  /** 完成百分比，自动限制在 0 到 100。 */
  percentage?: number
  /** 主题颜色。 */
  status?: ZtProgressStatus
  /** 尺寸，默认继承 ConfigProvider。 */
  size?: ZtComponentSize
  /** 是否显示进度文字。 */
  showText?: boolean
  /** 无法确定进度时使用循环动画，不向辅助技术报告百分比。 */
  indeterminate?: boolean
  /** 格式化完成率文字。 */
  format?: (percentage: number) => string
  /** 无障碍名称。 */
  ariaLabel?: string
}

export interface ZtConfigProviderProps {
  /** Default size for descendant components. Explicit component sizes take precedence. */
  size?: ZtComponentSize
  /** Color scheme, inherited by nested providers when omitted. */
  theme?: ZtTheme
  /** Base corner radius in pixels. Defaults to 11; 0 gives square corners. */
  borderRadius?: number
}

export interface ZtRadioGroupProps {
  /** 启用连体分段样式，可直接传递 segmented 属性。 */
  segmented?: boolean
  /** @deprecated 请使用 segmented；保留兼容原有用法。 */
  variant?: 'default' | 'segmented'
  name?: string
  modelValue?: unknown
  disabled?: boolean
  size?: ZtRadioSize
  status?: ZtRadioStatus
}

export interface ZtPasswordProps extends Omit<ZtInputProps, 'type'> {
  showToggle?: boolean
}

export interface ZtPasswordProps extends Omit<ZtInputProps, 'type'> {
  showToggle?: boolean
}

export type ZtSelectRemoteMethod = (
  keyword: string,
) => Promise<ZtSelectOption[]>;

export interface ZtSelectProps {
  /** 仅挂载可视选项窗口，适合大量数据；自定义选项需保持固定行高。 */
  virtual?: boolean;
  /** 虚拟列表行高（px），未设置时跟随 size。 */
  itemHeight?: number;
  /** 下拉列表最大高度（px），视口不足时自动缩小。 */
  height?: number;
  modelValue?: ZtSelectModelValue;
  options?: ZtSelectOption[];
  multiple?: boolean;
  /** 多选时折叠超出数量的标签，剩余项显示为 +N。 */
  collapseTags?: boolean;
  /** 开启 collapseTags 后最多展示的标签数，默认 1，最小为 1。 */
  maxCollapseTags?: number;
  filterable?: boolean;
  remote?: boolean;
  remoteMethod?: ZtSelectRemoteMethod;
  debounce?: number;
  clearable?: boolean;
  placeholder?: string;
  disabled?: boolean;
  size?: ZtComponentSize;
  noDataText?: string;
  remoteErrorText?: string;
}

export interface ZtSelectInstance {
  focus: (options?: FocusOptions) => void;
  blur: () => void;
  open: () => void;
  close: () => void;
}

export interface ZtSelectOption {
  label: string
  value: ZtSelectValue
  disabled?: boolean
}

export interface ZtFormGroupProps {
  title?: string
  description?: string
  disabled?: boolean
  bordered?: boolean
}

export interface ZtFormValidateOptions {
  trigger?: ZtFormValidateTrigger
  model?: Record<string, unknown>
  field?: string
}

export interface ZtStepProps {
  title?: string
  description?: string
  icon?: string | Component
  status?: ZtStepStatus
}

export type ZtBeforeClose = (
  reason: ZtOverlayCloseReason,
) => boolean | void | Promise<boolean | void>

export interface ZtDrawerProps extends ZtOverlayCommonProps {
  modelValue?: boolean
  subtitle?: string
  closeLabel?: string
  placement?: ZtDrawerPlacement
  /** Component density. */
  size?: ZtComponentSize
  /** Panel width for left/right drawers, in pixels or CSS units. */
  width?: number | string
  /** Panel height for top/bottom drawers, in pixels or CSS units. */
  height?: number | string
  /** Fill the viewport below this breakpoint; 0 disables it. */
  fullscreenBelow?: number
  bodyScroll?: boolean
  bodyPadding?: number | string
  loading?: boolean
  loadingText?: string
}

export type ZtBeforeClose = (
  reason: ZtOverlayCloseReason,
) => boolean | void | Promise<boolean | void>

export interface ZtDatePickerHoliday {
  /** Local calendar date, YYYY-MM-DD. */
  key: string;
  /** Holiday name displayed in the calendar cell. */
