export interface ZtTourStep {
  /** 目标元素、CSS 选择器或获取回调；缺失或已移除时居中显示。 */ target?:
    string | HTMLElement | (() => HTMLElement | null | undefined);
  /** 当前步骤标题。 */ title: string;
  /** 纯文本步骤说明，可由默认插槽替换。 */ description?: string;
  /** 当前步骤首选方位，默认 bottom。 */ placement?: ZtPopoverPlacement;
}

export interface ZtTourProps {
  /** 是否显示，支持 v-model，默认 false。 */ modelValue?: boolean;
  /** 受控步骤索引，默认 0；小数向下取整、越界值限制到有效范围、非有限值按 0。 */ current?: number;
  /** 步骤列表；空数组不创建浮层。 */ steps?: ZtTourStep[];
  /** 显示遮罩和目标高亮，默认 true。 */ mask?: boolean;
  /** 步骤变更时将目标滚入可视区域，默认 true。 */ scrollIntoView?: boolean;
  /** 提示面板宽度 px，窄屏自动收缩，默认 320。 */ width?: number;
  /** 初始层级，交由共用浮层管理器排序，默认 1000。 */ zIndex?: number;
}

export interface ZtTourEmits {
  (e: 'update:modelValue', open: boolean): void;
  (e: 'update:current', index: number): void;
  (e: 'change', index: number): void;
  (e: 'finish'): void;
  (e: 'close', reason: string): void;
}

export interface ZtWatermarkProps {
  /** 水印文字，支持多行；仅为视觉提示。 */ content?: string | string[];
  /** 可选图片 URL，加载失败触发 error 并显示文字水印。 */ image?: string;
  /** 单个水印内容宽度 px，默认 140。 */ width?: number;
  /** 单个水印内容高度 px，默认 64。 */ height?: number;
  /** [水平, 垂直] 单元间隔 px，默认 [80,80]。 */ gap?: [number, number];
  /** 每个单元旋转角度，默认 -22。 */ rotate?: number;
  /** 透明度 0–1，默认 0.15。 */ opacity?: number;
  /** 文字颜色，默认继承当前文本色。 */ color?: string;
  /** 文字大小 px，默认 14。 */ fontSize?: number;
  /** 覆盖层层级，默认 9。 */ zIndex?: number;
}

export interface ZtWatermarkEmits {
  (e: 'error', event: Event): void;
}

export interface ZtQRCodeProps {
  /** 编码的纯文本；空值显示空状态。 */ value?: string;
  /** 纠错等级，默认 M。 */ level?: ZtQRCodeLevel;
  /** 成品宽高 px，默认 160。 */ size?: number;
  /** 二维码周围空白模块数，默认 4。 */ margin?: number;
  /** 渲染为 SVG 或 Canvas，默认 svg。 */ renderAs?: 'svg' | 'canvas';
  /** 前景颜色，默认 #000000。请确保与背景有足够对比度。 */ color?: string;
  /** 背景颜色，默认 #ffffff。 */ background?: string;
  /** 辅助技术名称，默认 二维码。 */ label?: string;
}

export interface ZtQRCodeEmits {
  /** 编码、Canvas 渲染或下载失败。 */ (e: 'error', error: unknown): void;
  /** 下载已触发，参数为文件名。 */ (e: 'download', filename: string): void;
}

export interface ZtQRCodeInstance {
  /** 下载当前图像：SVG 模式保存 .svg，Canvas 保存 .png；成功触发下载返回 true。 */ download: (
    filename?: string,
  ) => boolean;
}

export type ZtSelectBoxRemoteRequest =
  | { mode: 'search'; keyword: string; page: number; pageSize: number }
  | { mode: 'batch'; keywords: string[] }

export interface ZtSelectBoxBatchMatch {
  keyword: string
  option: ZtSelectOption
}

export type ZtSelectBoxRemoteResult =
  | { mode: 'search'; options: ZtSelectOption[]; total: number }
  | { mode: 'batch'; matches: ZtSelectBoxBatchMatch[] }

export type ZtSelectBoxRemoteMethod = (
  request: ZtSelectBoxRemoteRequest,
) => Promise<ZtSelectBoxRemoteResult>

export interface ZtSelectOption {
  label: string
  value: ZtSelectValue
  disabled?: boolean
}
